import re

def configure_run(dockerfile,stage_number,run_number):
    if not isinstance(stage_number,int) or stage_number<1 or not isinstance(run_number,int) or run_number<1:
        raise ValueError("stage and RUN numbers are one-based positive integers")
    lines=dockerfile.splitlines(keepends=True);stage=0;run=0
    for index,line in enumerate(lines):
        stripped=line.lstrip()
        if re.match(r"FROM\s+",stripped,re.I):
            stage+=1;run=0;continue
        if stage==stage_number and re.match(r"RUN\s+",stripped,re.I):
            run+=1
            if run==run_number:
                if stripped.rstrip("\r\n").endswith("\\"):
                    raise ValueError("multiline RUN must be normalized before editing")
                newline="\r\n" if line.endswith("\r\n") else "\n"
                indent=line[:len(line)-len(stripped)]
                lines.insert(index,indent+'SHELL ["/bin/bash","-o","pipefail","-c"]'+newline)
                return "".join(lines)
    raise ValueError("target RUN not found")
```

